public class SecureFileReader {
    private final Path path;

    public SecureFileReader(Path path) {
        this.path = path;
    }

    // Encapsulates the NIO complexity, hiding the buffer and channel lifecycle
    public String readContent() throws DataAccessException {
        try (FileChannel channel = FileChannel.open(path, StandardOpenOption.READ)) {
            ByteBuffer buffer = ByteBuffer.allocate(1024);
            channel.read(buffer);
            buffer.flip();
            return StandardCharsets.UTF_8.decode(buffer).toString();
        } catch (IOException e) {
            throw new DataAccessException("Failed to read file: " + path, e);
        }
    }
}
